{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/** The command: `dump <file>`, `get <file> <key>`, `load <base> <site>` and `origin <base> <site>`. */

import { existsSync, readFileSync } from 'node:fs'
import { parse as parseEnv } from './env.js'
import { IniError, parse as parseIni } from './ini.js'
import { merge } from './layer.js'
import { coerce, SETTINGS, setting } from './schema.js'

const USAGE = 'usage: cli.js dump <file>|get <file> <key>|load <base> <site>|origin <base> <site>'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** One INI layer for `dump`/`get`, refused at its own position when the grammar rejects it. */
function iniLayer(name, path) {
  if (!existsSync(path)) fail(`cannot read ${path}`)
  try {
    return { name, values: parseIni(readFileSync(path, 'utf8')) }
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`${path}:${error.line}:${error.column}: ${error.message}`)
  }
}

/**
 * One INI layer for `load`/`origin`: refused at its own position when the grammar rejects it, and again,
 * at the value's position, for the first key it sets that the schema does not know.
 */
function loadIniLayer(name, path) {
  if (!existsSync(path)) fail(`cannot read ${path}`)
  let parsed
  try {
    parsed = parseIni(readFileSync(path, 'utf8'))
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`${path}:${error.line}:${error.column}: ${error.message}`)
  }
  const values = new Map()
  for (const [key, entry] of parsed) {
    if (setting(key) === undefined) fail(`${path}:${entry.line}:${entry.column}: unknown setting ${key}`)
    values.set(key, { text: entry.text, line: entry.line, column: entry.column, source: path, layer: name })
  }
  return { name, values }
}

/** The environment layer, read from standard input, refused at its own position when the grammar rejects it. */
function envLayer(text) {
  let parsed
  try {
    parsed = parseEnv(text)
  } catch (error) {
    return fail(`<stdin>:${error.line}:${error.column}: ${error.message}`)
  }
  const values = new Map()
  for (const [key, entry] of parsed) {
    values.set(key, { text: entry.text, line: entry.line, column: entry.column, source: '<stdin>', layer: 'env' })
  }
  return { name: 'env', values }
}

const argv = process.argv.slice(2)
const mode = argv[0]
const arity = { dump: 2, get: 3, load: 3, origin: 3 }
